values
  ('37113ce0-9c41-44a6-94c6-f0477d2e2e81', 'ja', 'rollin-challenge', 'Rollin\'チャレンジ', 'ブレイブガールズ「Rollin''」が4年越しに逆走行し広まったTikTokダンスチャレンジ。', '2017年発売の「Rollin''」のコメント欄まとめ動画が話題となり、2021年2月に音源チャートを逆走行した。ユジョン・ウンジ・ユナらメンバーがTikTokにチャレンジ動画を投稿して拡散し、逆走行神話の象徴としてK-POPチャート史に名を刻んだ。', '2021年2〜3月ブレイブガールズのメンバーがTikTokに投稿したチャレンジ動画と、ファンコミュニティのコメントまとめ動画の拡散から始まった', '逆走行・再発見のストーリーを語る際に引用される', NULL, array['롤린 챌린지', 'Rollin'' Challenge', 'ブレイブガールズ逆走行']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
