values
  ('d722373f-cdad-4980-bd2a-6375de65c229', 'ja', 'hwanijini', 'ファニジニ', '2曲を1曲のようにつなげるミックスコンサートで人気を集めた「爆笑クラブ」の最長寿コーナー。', '異なる2曲(例:パク・サンミンの「ヘバラギ」とビートルズの「Let It Be」)を1曲のように自然につなげて歌う「ミックスコンサート」形式で、韓国初のスタンドアップコメディ番組「爆笑クラブ」を代表する長寿コーナーだった。', '2002年11月1日「爆笑クラブ」初回放送から2005年8月まで放送', '曲を組み合わせるコント形式の元祖的事例として言及される', NULL, array['화니지니', '爆笑クラブ ファニジニ']::text[], '[{"text": "この曲つなぎ、完全にファニジニ風だわ", "situation": "カカオトーク"}, {"text": "ミックスコンサートの元祖はファニジニでしょ", "situation": "SNSコメント"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('5371a917-e55b-4f3b-b47a-4510f03b8180', 'ja', 'babyvox-yayaya', 'ベイビーヴォックス「ヤヤヤ」', '1998年、ベイビーヴォックスのパワフルな振り付けで話題を呼んだタイトル曲。', '1998年発売のベイビーヴォックス2集のタイトル曲「ヤヤヤ」は、曲の雰囲気とは異なるパワフルな振り付けで大きな人気を集め、以後「ダンスの上手いガールズグループ」というベイビーヴォックスのイメージを作った曲となった。', '「ヤヤヤ」は1998年発売のベイビーヴォックス2集のタイトル曲で、曲の雰囲気とは異なるパワフルな振り付けが話題を集めた。ユ・スンジュンらを指導した振付師イ・ヨンファンが手がけたいわゆる「アンニョンダンス」は、少女風の動作と激しい動作を行き来する構成でファンの間で大きな反響を呼んだ。メンバーは1日8時間に及ぶ練習とともに3ヶ月間テッキョンを習い振り付けを完成させたと伝えられる。この舞台をきっかけにベイビーヴォックスは「ダンスの上手いガールズグループ」というイメージを確立した。', '1990年代末のガールズグループダンスの代表事例として言及できる', NULL, array['베이비복스 야야야', 'ヤヤヤ', 'Baby V.O.X']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('73b417c4-092c-4632-b57b-ebbfeb49a8ef', 'ja', 'cheonsaengyeonbun', '天生縁分(チョンセンヨンブン)', '2002年、お見合いバラエティブームを開いたカップルマッチング番組。', '2002年10月に始まったMBCのカップルマッチングバラエティで、選択ではなくマッチング後にゲームを一緒に行う方式で2000年代のお見合いバラエティブームの始まりとなった。', '2002年6月MBC週末バラエティ「目標達成土曜日」の1コーナーとして始まり、同年10月26日に独立編成された番組で、カン・ホドンが初めて自分の名前を冠したMCとして起用された。芸能人の男女がゲームと会話を通じてカップルになる過程を見せる形式で、それまでの「青春デート」「愛のスタジオ」など一般人対象の恋愛番組とは異なり、芸能人の人間味を際立たせて人気を集めた。以後続くお見合い・カップルマッチングバラエティジャンルの元祖格とされる。', '2000年代のお見合いバラエティブームの事例として言及される', NULL, array['천생연분', 'カン・ホドンの天生縁分']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('20a1f0bb-1979-46f7-a7d5-4e2b03ff6c82', 'ja', 'daehanminguk-jjakjjakjjakjjakjjak', 'テ〜ハンミングク パチパチパチパチパチ', '2002年ワールドカップで赤い悪魔が広めた代表的な応援コール。', '2002年日韓ワールドカップの際、赤い悪魔応援団が主導した「テ〜ハンミングク(パチパチ パチパチパチ)」の手拍子コールが、国民的な応援文化として広まった。元々は水原三星サポーターズの「ス〜ウォンサムソン」コールを変形したもので、ワールドカップをきっかけに国民的な応援コールとなった。', '水原三星サポーターズ「グランブルー」の応援コール「ス〜ウォンサムソン(パチパチパチパチパチ)」から派生したとされる。1997年頃、全国のプロサッカーサポーターが集まって赤い悪魔を結成した際、4文字のコールを代表チームに合わせて「テ〜ハンミングク」に変えて歌い始めた。2002年日韓ワールドカップ期間中、街頭応援の象徴的なコールとして爆発的に広まり、国民的な挨拶のように使われた。ワールドカップ公式アルバム収録曲にも取り入れられた。このコールの著作権をめぐって、後に故シン・ヘチョルが異議を唱え、論争になったこともある。', '代表戦の応援時、手拍子コールとしてそのまま使える', NULL, array['대한민국 짝짝짝짝짝', 'テ〜ハンミングク', 'パチパチ拍手']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
