values
  ('8310543f-7e46-4af8-bec4-039e4482cb25', 'ja', 'onigiri-dance', 'おにぎりダンス', '韓国のアニメーションユーチューバーチームが作ったキャラクターダンスアニメーションミーム。', '韓国のアニメーションユーチューバーチーム「VIVINOS(ビビノス)」が2021年10月に投稿した「Onigiri Dance」というアニメダンス映像が始まりである。2022年に入りTikTokやYouTubeショートでゼロツーダンス、アンカジョンダンスと並ぶ代表的なダンスミームの一つとして定着し、様々なパロディを生んだ。', 'ユーチューバーチーム、ビビノスが作ったアニメーション「Onigiri Dance」(2021年10月投稿、2022年拡散)', '可愛らしいアニメ風ダンスミームとして気軽に楽しめる', NULL, array['오니기리 댄스', 'Onigiri Dance']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
